/**
 * Pending invites hold a seat: unaccepted, unrevoked and unexpired. Revoking
 * an invitation or letting it expire frees its seat immediately.
 */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const now = toIsoTimestamp(new Date());
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, now),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Every currently pending email in this org, lower-cased for comparison. */
export async function listPendingInvitationEmails(
  orgId: OrgId,
): Promise<ReadonlySet<string>> {
  const rows = await listPendingInvitations(orgId);
  return new Set(rows.map((row) => row.email.toLowerCase()));
}

