/**
 * Unpins every one of a user's sessions from an org they just left, so the
 * app stops defaulting to a workspace it can no longer resolve an actor in.
 * Their other sessions (and other orgs) are untouched.
 */
export async function clearActiveOrgForUser(
  userId: UserId,
  orgId: OrgId,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(eq(sessions.userId, userId), eq(sessions.activeOrgId, orgId)))
    .run();
}

/** Unpins every session pointed at a workspace that has just been deleted. */
export async function clearActiveOrgForOrg(orgId: OrgId): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.activeOrgId, orgId))
    .run();
}

